---@class ActivityNightCatBossMgr
---@field GetInstance fun(self:ActivityNightCatBossMgr):ActivityNightCatBossMgr
local ActivityNightCatBossMgr = Class("ActivityNightCatBossMgr", Singleton)

function ActivityNightCatBossMgr:__init()
    ---@type NightCatBossComponent
    self._nightCatBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.NightCatBossComponent)
end

function ActivityNightCatBossMgr:__delete()
end

--region public
function ActivityNightCatBossMgr:RankRewardReq(activityId)
    GameUtils.Request(Interfaces.NightCatBossRank, {activityUuid=activityId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        self._nightCatBossComponent:GetRankDojo():Fill(jsonData)
        Events.Broadcast(Constants.EventNames.ActivityNightCatRankRewardReq)
    end)
end

function ActivityNightCatBossMgr:LoadRankRewardVo()
    local allVo = CfUtils.GetCf(AutoIds.IdSetting6101, "NightCatBossRankRewardVo", true)
    for _, vo in ipairs(allVo) do
        ---@type NightCatBossRankRewardVo
        local rankRewardVo = vo
        local rewards = {}
        for i, reward in ipairs(rankRewardVo.reward) do
            local t = {
                goodsId = reward,
                num = rankRewardVo.rewardNum[i]
            }
            table.insert(rewards, t)
        end
        vo.rewards = rewards
    end
    return allVo
end

function ActivityNightCatBossMgr:GetRewardsByRankNum(playerRank)
    local allVo = self:LoadRankRewardVo()
    local t = {}
    for i, v in pairs(allVo) do
        ---@type NightCatBossRankRewardVo
        local rankRewardVo = v
        if checkNumber(rankRewardVo.upperLimit) <= playerRank and checkNumber(rankRewardVo.lowerLimit) >= playerRank then
            t =  checkTable(rankRewardVo.rewards)
        end
    end
    return t
end
--endregion public


return ActivityNightCatBossMgr